(x, y, t) => {
  const wx1 = Math.sin(x*0.02+t*0.3)*15+Math.cos(y*0.015-t*0.2)*10;
  const wy1 = Math.cos(y*0.02-t*0.25)*15+Math.sin(x*0.018+t*0.35)*10;
  const sx1 = x+wx1, sy1 = y+wy1;
  const wx2 = Math.sin(sx1*0.015-t*0.2)*12+Math.cos(sy1*0.02+t*0.15)*8;
  const wy2 = Math.cos(sx1*0.018+t*0.25)*10+Math.sin(sy1*0.012-t*0.3)*12;
  const sx = sx1+wx2, sy = sy1+wy2;
  const src = [
    [160+Math.sin(t*0.6)*100,80+Math.cos(t*0.4)*50,0.08,2.0,1.0],
    [320+Math.cos(t*0.5)*100,160+Math.sin(t*0.7)*50,0.1,1.7,0.8],
    [240+Math.sin(t*0.3+2)*140,120+Math.cos(t*0.5+1)*90,0.06,2.3,1.2],
    [120+Math.cos(t*0.8+1)*80,180+Math.sin(t*0.6+3)*60,0.12,1.5,0.9],
    [360+Math.sin(t*0.4+4)*90,60+Math.cos(t*0.9+2)*70,0.07,2.6,1.1],
    [240+Math.cos(t*0.35+5)*120,200+Math.sin(t*0.55)*80,0.09,1.9,0.7],
    [80+Math.sin(t*0.45+3)*110,40+Math.cos(t*0.65+1)*65,0.11,2.1,0.85],
    [400+Math.cos(t*0.55+2)*95,200+Math.sin(t*0.75+4)*75,0.065,1.8,1.15]
  ];
  let aS=0,iS=0,hrm=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    aS+=Math.sin(d*f-t*sp)*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*w;
    hrm+=Math.sin(d*f*1.3-t*sp*0.8+0.7)*w;
  }
  const n=7.6,act=aS/n,inh=iS/n,h=hrm/n;
  const bg1=(Math.sin(sx*0.04+sy*0.025+t*0.8)+Math.sin(sx*0.03-sy*0.04+t*1.1))/2;
  const bg2=Math.sin((sx+sy)*0.12+t*2.5)*0.2+Math.sin((sx-sy)*0.1-t*2)*0.2;
  const bg3=Math.sin(sx*0.07-sy*0.06+t*1.5)*0.15+Math.cos(sx*0.05+sy*0.08-t*0.9)*0.15;
  const bg=bg1+bg2+bg3;
  const cx=240,cy=120,dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=(Math.sin(dist*0.05-ang*3-t*1.5)+Math.sin(dist*0.04+ang*4-t*1.2))*0.4;
  const sp2=(Math.sin(dist*0.08+ang*2+t*0.7)+Math.cos(dist*0.06-ang*5+t*1.1))*0.2;
  const fine=Math.sin(sx*0.25+t*1.5)*Math.sin(sy*0.25-t*1.2)*0.15;
  const cell=Math.tanh((Math.sin(sx*0.15)*Math.sin(sy*0.15)+Math.sin((sx+sy)*0.1+t)*0.5)*1.5)*0.3;
  const rd1=Math.tanh((act-inh*0.7+bg*0.3+sp1)*2.2);
  const rd2=Math.tanh((h-act*0.5+bg2*0.4+sp2)*1.8);
  const reaction=rd1*0.65+rd2*0.2+cell*0.1+fine*0.05;
  const vign=1.0-Math.sqrt((x-240)**2+(y-120)**2)/320;
  const blend=reaction*0.5+0.5;
  const pal=[
    [5,12,52],[10,45,95],[15,90,120],[25,140,130],
    [80,175,110],[180,190,65],[210,155,55],[200,110,60],
    [170,60,60],[120,35,55],[60,18,50],[5,12,52]
  ];
  const idx=blend*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const r=pal[i][0]+(pal[i+1][0]-pal[i][0])*f;
  const g=pal[i][1]+(pal[i+1][1]-pal[i][1])*f;
  const b=pal[i][2]+(pal[i+1][2]-pal[i][2])*f;
  const lum=0.85+Math.sin(reaction*Math.PI)*0.15;
  const edge=Math.abs(reaction)>0.65?1.2:1.0;
  const breath=0.92+Math.sin(t*0.4)*0.08;
  const vf=Math.max(0.3,vign)*breath;
  return[
    Math.min(255,r*lum*edge*vf)|0,
    Math.min(255,g*lum*edge*vf)|0,
    Math.min(255,b*lum*edge*vf)|0
  ];
}
